Lemma copy_mspec N src : okN N src ->
  mspec (copy src) (fun s' => okN N s' /\ s_words s' = s_words src /\ s_neg s' = s_neg src /\ s_alloc s' = s_alloc src
                             /\ capacity s' = capacity src) 1 (BB N).
Proof.
